// CompletionResult is exactly one of its members, chosen by "status".
type CompletionResult struct {
	CompletionAccepted *CompletionAccepted
	CompletionRejected *CompletionRejected
}

const (
	CompletionResultTagAcceptedForVerification = "accepted_for_verification"
	CompletionResultTagRejected                = "rejected"
)

// Tag returns the "status" value of the member that is set.
func (u CompletionResult) Tag() string {
	switch {
	case u.CompletionAccepted != nil:
		return "accepted_for_verification"
	case u.CompletionRejected != nil:
		return "rejected"
	}
	return ""
}

func (u CompletionResult) MarshalJSON() ([]byte, error) {
	switch {
	case u.CompletionAccepted != nil:
		v := *u.CompletionAccepted
		v.Status = "accepted_for_verification"
		return json.Marshal(v)
	case u.CompletionRejected != nil:
		v := *u.CompletionRejected
		v.Status = "rejected"
		return json.Marshal(v)
	}
	return nil, fmt.Errorf("contract: CompletionResult has no member set")
}

func (u *CompletionResult) UnmarshalJSON(data []byte) error {
	var head struct {
		Tag string `json:"status"`
	}
	if err := json.Unmarshal(data, &head); err != nil {
		return fmt.Errorf("contract: decode CompletionResult: %w", err)
	}
	switch head.Tag {
	case "accepted_for_verification":
		var v CompletionAccepted
		if err := json.Unmarshal(data, &v); err != nil {
			return fmt.Errorf("contract: decode CompletionResult accepted_for_verification: %w", err)
		}
		*u = CompletionResult{CompletionAccepted: &v}
	case "rejected":
		var v CompletionRejected
		if err := json.Unmarshal(data, &v); err != nil {
			return fmt.Errorf("contract: decode CompletionResult rejected: %w", err)
		}
		*u = CompletionResult{CompletionRejected: &v}
	default:
		return fmt.Errorf("contract: unknown CompletionResult status %q", head.Tag)
	}
	return nil
}

